changeSet.sql:
DO $$
DECLARE
    r RECORD;
BEGIN
    FOR r IN (
        SELECT conname
        FROM pg_constraint
        WHERE conrelid = 'public.delivery_installations'::regclass
          AND contype = 'c'
          AND pg_get_constraintdef(oid) LIKE '%status%'
    ) LOOP
        EXECUTE 'ALTER TABLE public.delivery_installations DROP CONSTRAINT ' || quote_ident(r.conname);
    END LOOP;
END $$;

ALTER TABLE public.delivery_installations ADD CONSTRAINT delivery_installations_status_check
    CHECK (status IN ('ASSIGNED', 'IN_PROGRESS', 'DELIVERED', 'INSTALLED', 'WAITING_PO_CONFIRMATION', 'COMPLETED', 'FAILED'));

ALTER TABLE public.delivery_installations ADD COLUMN IF NOT EXISTS estimated_end_time timestamptz;
ALTER TABLE public.delivery_installations ADD COLUMN IF NOT EXISTS completion_photos jsonb DEFAULT '[]'::jsonb;
ALTER TABLE public.delivery_installations ADD COLUMN IF NOT EXISTS completion_note text;
ALTER TABLE public.delivery_installations ADD COLUMN IF NOT EXISTS rework_notes text;

ALTER TABLE public.warranty_claims ADD COLUMN IF NOT EXISTS scheduled_at timestamptz;
ALTER TABLE public.warranty_claims ADD COLUMN IF NOT EXISTS estimated_end_time timestamptz;
